local sE=N.DRONES and N.DRONES[bE.unit_id]
if sE and sE.late and nE>0 then
local tE=1/nE
rE=rE*tE/(tE+(tonumber(sE.max)or 0)*(tonumber(sE.late.dmg)or 0)*(tonumber(sE.hits)or 1)/math.max(0.1,tonumber(sE.late.cd)or 4))
end
hE=hE+rE
elseif pE.id==doc[1897]then
hE=hE+(tonumber(qE.dmg_buff)or 0)*0.25
elseif pE.id==doc[1898]then
hE=hE+(tonumber(qE.dmg_buff)or 0)*iE
elseif pE.id==doc[1899]then
if fE.magic then
hE=0
else
hE=hE+(tonumber(qE.dmg_buff)or 0)*0.3
end
elseif pE.id==doc[1900]then
