function Q.buildPath()
Q.samples={}
local kwb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not kwb then
return
end
for lwb,mwb in pairs(kwb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[lwb.Name])then
local nwb={}
for owb,pwb in ipairs(mwb.points or{})do
table.insert(nwb,pwb.part.Position)
end
local qwb=0
for rwb=2,#nwb do
qwb=qwb+(nwb[rwb]-nwb[rwb-1]).Magnitude
end
local swb=0
for twb=2,#nwb do
local uwb,vwb=nwb[twb-1],nwb[twb]
local wwb=(vwb-uwb).Magnitude
local xwb=math.max(1,math.floor(wwb/2))
for ywb=0,xwb-1 do
local zwb=uwb:Lerp(vwb,ywb/xwb)
table.insert(Q.samples,{pos=zwb,prog=(swb+wwb*ywb/xwb)/math.max(1,qwb),lane=lwb.Name})
end
swb=swb+wwb
end
if nwb[#nwb]then
table.insert(Q.samples,{pos=nwb[#nwb],prog=1,lane=lwb.Name})
end
end
end
local Awb,Bwb,Cwb={},0,0
for Dwb,Ewb in ipairs(Q.samples)do
local Fwb=tostring(Ewb.lane)
if not Awb[Fwb]then
Bwb=Bwb+1
end
Awb[Fwb]=(Awb[Fwb]or 0)+1
Cwb=Cwb+1
end
Q.laneCount={n=Bwb,by=Awb,avg=Bwb>0 and Cwb/Bwb or 1}
end
